const KEY='itquest-v1', HOUSEHOLD_KEY='itquest-household-v1';
const DEFAULT_VOLUME=60, AUDIO_VERSION=3;
const LEVELS=[
  {level:1,xp:0},{level:2,xp:120},{level:3,xp:280},{level:4,xp:460},{level:5,xp:660},
  {level:6,xp:880},{level:7,xp:1120},{level:8,xp:1380},{level:9,xp:1660},{level:10,xp:1960}
];
const CHARACTERS={
  rei:{name:'レイ',role:'キャラ１',color:'orange',tag:'短く、強く。たまに優しい',style:'短く鋭い。次へ進ませる',fit:'テンポよく集中したい人',lines:{idle:['知識は、次の一手を強くする。','準備はいい？ 行こう。'],correct:['いい。そのまま行こう。','正解。キレてる。'],wrong:['大丈夫。次で取り返す。'],complete:['やるじゃん。次も行こう。']}},
  zack:{name:'ザック',role:'キャラ２',color:'blue',tag:'余裕のある兄キャラ',style:'多く語らず、ゆったり包む',fit:'焦らず自分のペースで続けたい人',lines:{idle:['焦らなくていい。考える時間はある。','今日も来たか。えらいじゃん。'],correct:["Yeah. That's it.",'その調子だ。'],wrong:['大丈夫。もう一回いこう。','まだ終わってない。ここからだ。'],complete:['いいね。その調子、続けよう。']}},
  nadi:{name:'ナディ',role:'キャラ３',color:'purple',tag:'クールな見た目で、めちゃくちゃ褒める',style:'小さな頑張りも見逃さず認める',fit:'たくさん褒められながら続けたい人',lines:{idle:['ここに来ただけでも素敵だよ。','今日の一歩、もう始まってるよ。'],correct:['すごい！ちゃんと力がついてるよ。','完璧！今の判断、とっても良かった。'],wrong:['大丈夫。挑戦したことがもうすごいよ。'],complete:['ここまで本当によく頑張ったね！']}},
};
const REWARD_NAMES={2:'ストリートジャケット',3:'タクティカル武器',4:'軽装バトルウェア',5:'強化アーマー',6:'トレーニングウェア',7:'レア武器',8:'特別カラー',9:'上位戦闘装備',10:'模擬テスト記念エンブレム'};
const fresh=()=>({xp:0,answered:0,correct:0,completed:[],missionIndex:0,history:{},seenQuestionIdsByTopic:{},reviewFilter:'all',pastHistory:{},achievements:[],selected:'rei',companionChosen:false,lastStudy:null,streak:0,unlocked:[],session:null,bgm:true,volume:DEFAULT_VOLUME,audioVersion:AUDIO_VERSION});
let household=JSON.parse(localStorage.getItem(HOUSEHOLD_KEY)||'null')||{profiles:[],activeId:null};
let state=fresh();
const pinHash=pin=>{let h=2166136261;for(const c of pin)h=Math.imul(h^c.charCodeAt(0),16777619);return (h>>>0).toString(36)};
const profileKey=id=>`itquest-profile-${id}`;
function activeProfile(){return household.profiles.find(p=>p.id===household.activeId)}
function loadProfile(id){
  household.activeId=id;
  localStorage.setItem(HOUSEHOLD_KEY,JSON.stringify(household));
  const stored=JSON.parse(localStorage.getItem(profileKey(id))||'null')||{};
  state={...fresh(),...stored};
  state.seenQuestionIdsByTopic=state.seenQuestionIdsByTopic||{};
  state.reviewFilter=state.reviewFilter||'all';
  Object.values(state.history).forEach(h=>{
    if(!Number.isInteger(h.masteryStage))h.masteryStage=h.nextReviewAt>Date.now()?Math.min(h.correctCount||0,5):0;
    if(!Number.isInteger(h.correctStreak))h.correctStreak=0;
    if(!Number.isInteger(h.recentIncorrectCount))h.recentIncorrectCount=h.masteryStage?0:Math.min(h.incorrectCount||0,3);
  });
  // 旧版の完了履歴も、順番に進む新しい学習コースへ引き継ぐ。
  state.missionIndex=Math.max(0,Math.min(TOPICS.length,Number.isInteger(state.missionIndex)?state.missionIndex:state.completed.length));
  if(state.selected==='mina')state.selected='nadi';
  if(!CHARACTERS[state.selected])state.selected='rei';
  if((stored.audioVersion||0)<AUDIO_VERSION){
    state.volume=DEFAULT_VOLUME;
    state.audioVersion=AUDIO_VERSION;
    localStorage.setItem(profileKey(id),JSON.stringify(state));
  }
}
function leaveProfile(){household.activeId=null;localStorage.setItem(HOUSEHOLD_KEY,JSON.stringify(household));state=fresh();clearInterval(bgmTimer);bgmTimer=null;screen='home';}
if(household.activeId&&activeProfile())loadProfile(household.activeId);
let screen='home', answerStarted=0, mockTimer=null;
const save=()=>{const p=activeProfile();if(p)localStorage.setItem(profileKey(p.id),JSON.stringify(state));};
const today=()=>new Date().toISOString().slice(0,10);
const level=()=>LEVELS.filter(x=>state.xp>=x.xp).at(-1).level;
const xpToNext=()=>{const next=LEVELS.find(x=>x.level===level()+1);return next?next.xp-state.xp:0};
const levelProgress=()=>{const current=LEVELS.find(x=>x.level===level()),next=LEVELS.find(x=>x.level===level()+1);return next?Math.min(100,(state.xp-current.xp)/(next.xp-current.xp)*100):100};
const MISSION_QUESTION_COUNT=10, REVIEW_QUESTION_COUNT=20, REVIEW_FILTER_THRESHOLD=60;
const topic=()=>TOPICS[Math.min(state.missionIndex,TOPICS.length-1)];
const topicPosition=()=>Math.min(state.missionIndex,TOPICS.length-1);
function curriculumStage(){const i=topicPosition();if(i<3)return {name:'ステップ1：ITの土台',goal:'コンピュータとネットワークの基本語を、役割で説明できるようにしよう。'};if(i<6)return {name:'ステップ2：Webと安全',goal:'Webの流れと、安全に使うための判断を結び付けよう。'};if(i<10)return {name:'ステップ3：仕組みを考える',goal:'データ、手順、計算、AIを組み合わせて問題文を読もう。'};if(i<14)return {name:'ステップ4：会社で使うIT',goal:'データ活用、経営、会計、法務を事例から判断しよう。'};return {name:'ステップ5：実務の判断',goal:'開発・運用・監査の役割を比べ、過去問形式の選択肢を見分けよう。'};}
function levelLearningFocus(value=level()){if(value<=2)return '用語の役割を確認する';if(value<=5)return '似た仕組みを比べる';if(value<=8)return '計算と事例から判断する';return '過去問形式の選択肢を見分ける';}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dialogueText=s=>esc(s).replace(/([\u30a1-\u30f6\u30fc]{2,}|[A-Za-z0-9][A-Za-z0-9.+#-]*)/g,'<span class="no-break">$1</span>');
const regexEscape=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const readingPattern=new RegExp(Object.keys(READING_GUIDE).sort((a,b)=>b.length-a.length).map(regexEscape).join('|'),'g');
const studyText=s=>esc(s).replace(readingPattern,term=>`<ruby>${term}<rp>（</rp><rt>${READING_GUIDE[term]}</rt><rp>）</rp></ruby>`);
let audioContext=null,bgmTimer=null,bgmStep=0;
const isMissionScreen=()=>['lesson','quiz','feedback','complete'].includes(screen);
function audio(){audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();return audioContext;}
function tone(freq,duration=.2,volume=.03,type='sine',delay=0){if(!isMissionScreen())return;const ctx=audio(),osc=ctx.createOscillator(),gain=ctx.createGain(),now=ctx.currentTime+delay,scaled=volume*(state.volume/100)*8;osc.type=type;osc.frequency.setValueAtTime(freq,now);gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(Math.max(.0001,scaled),now+.025);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);osc.connect(gain).connect(ctx.destination);osc.start(now);osc.stop(now+duration+.02);}
function setBgm(enabled){state.bgm=enabled;save();clearInterval(bgmTimer);bgmTimer=null;}
function stopAudioPlayback(){clearInterval(bgmTimer);bgmTimer=null;if(audioContext?.state==='running')audioContext.suspend();}
function sound(kind){if(kind==='correct'){tone(659,.11,.09,'triangle');tone(880,.24,.09,'sine',.09)}if(kind==='combo'){tone(523,.18,.025,'sine');tone(659,.2,.025,'sine',.09);tone(784,.28,.02,'triangle',.18)}if(kind==='wrong'){tone(155,.22,.028,'triangle');}if(kind==='complete'){tone(392,.18,.04,'triangle');tone(523,.22,.035,'triangle',.12);tone(659,.38,.03,'sine',.25)}}
function termInfo(term){
  const info=TERM_DEFINITIONS[term];
  if(info)return info;
  console.warn(`用語辞書に未登録です: ${term}`);
  return `「${term}」の解説は準備中です。`;
}
function guideSection(title,items,className='exam-points'){
  if(!items?.length)return '';
  return `<section class="lesson-card"><h2>${title}</h2><ul class="${className}">${items.map(x=>`<li>${studyText(x)}</li>`).join('')}</ul></section>`;
}
function character(name=state.selected){return CHARACTERS[name]||CHARACTERS.rei}
function daysSince(dateString){return dateString?Math.floor((Date.now()-new Date(`${dateString}T00:00:00`).getTime())/864e5):0}
function homeVoiceSituation(){if(state.lastStudy&&daysSince(state.lastStudy)>=7)return 'longAbsence';if(state.streak>=2)return 'continued';return 'visit'}
function sessionSummarySituation(){const s=state.session;if(s?.levelUps?.length)return 'levelUp';if(s?.correct===10)return 'correct';if(s?.answers?.some(a=>a.voiceSituation==='comebackCorrect'))return 'comebackCorrect';if((s?.correct||0)>=8)return 'memoryCorrect';if((s?.correct||0)<=5)return 'wrong';return 'nextLevel'}
function pickLine(kind='visit'){
  const idleSituation=screen==='quiz'&&state.session?.index>0?'next':screen==='mockSetup'?'mockExam':homeVoiceSituation();
  const situation={idle:idleSituation,complete:sessionSummarySituation()}[kind]||kind;
  const lines=VOICE_TANK?.[state.selected]?.[situation]||character().lines[kind]||character().lines.idle;
  const salt=[...situation].reduce((n,c)=>n+c.charCodeAt(0),0);
  return dialogueText(lines[(state.answered+state.completed.length+state.streak+salt)%lines.length]);
}
function answerRun(correct=true){let n=0;for(const a of [...(state.session?.answers||[])].reverse()){if(a.correct!==correct)break;n++}return n}
function companionChance(kind){
  if(screen.startsWith('mock'))return 0;
  if(screen==='complete')return 1;
  const s=state.session,index=s?.index||0,q=s&&QUESTIONS.find(x=>x.id===s.questions[index]);
  if(kind==='comebackCorrect')return .9;
  if(kind==='wrong'&&answerRun(false)>=2)return .9;
  if((kind==='correct'||kind==='memoryCorrect')&&answerRun(true)>=2)return .75;
  if(screen==='quiz'&&q&&!state.history[q.id])return .7;
  if(s&&index>=8)return .85;
  return .32;
}
function shouldShowCompanion(kind='idle'){
  // Outside a mission the selected navigator remains visible. During a
  // mission each newly rendered scene gets a fresh, intentionally irregular roll.
  if(!isMissionScreen())return true;
  return Math.random()<companionChance(kind);
}
const POSE_BY_MOOD={neutral:0,thinking:1,down:2,cheer:3};
function moodForSituation(kind='idle'){
  if(kind==='wrong')return 'down';
  if(['complete','levelUp'].includes(kind))return 'cheer';
  if(['correct','comebackCorrect','memoryCorrect'].includes(kind)){
    const correctMoods=['cheer','neutral','thinking'];
    return correctMoods[(Math.max(1,answerRun(true))-1)%correctMoods.length];
  }
  if(['weakUnit','mockExam','next'].includes(kind)||screen==='quiz'||screen==='lesson')return 'thinking';
  return 'neutral';
}
function characterArt(id=state.selected,variant='main',mood='neutral'){
  // The compact crops are deliberately head-and-shoulders only: keep at least
  // half of the face visible and never reach the chest logo area.
  let resolvedMood=mood;
  if(screen==='home'&&mood==='neutral'){
    if(variant==='spot')resolvedMood='thinking';
    if(variant==='hero-art')resolvedMood='cheer';
  }
  const pose=POSE_BY_MOOD[resolvedMood]??POSE_BY_MOOD.neutral;
  const hidden=variant==='coach-art'&&!shouldShowCompanion('idle')?' hidden':'';
  return `<div class="character-art ${id} ${variant} pose-${pose} mood-${resolvedMood}${hidden}" role="img" aria-label="${character(id).name}（${resolvedMood}）"></div>`;
}
function companionFace(kind='idle'){if(!shouldShowCompanion(kind))return '';const mood=moodForSituation(kind);return `<aside class="feedback-companion ${state.selected}" data-mood="${mood}">${characterArt(state.selected,'feedback-face',mood)}</aside>`}
function companionSpot(kind='idle'){if(!shouldShowCompanion(kind))return '';const place=(state.answered+state.completed.length)%2?'top':'bottom',mood=moodForSituation(kind);return `<aside class="companion-spot ${place} ${state.selected}" data-mood="${mood}">${characterArt(state.selected,'spot',mood)}<div><small>${character().name}</small><p>「${pickLine(kind)}」</p></div></aside>`}
const questionLevel=q=>q.level||TOPICS.find(t=>t.id===q.topicId)?.level||1;
const reviewLevels=()=>[level(),Math.max(1,level()-1)];
const isDue=q=>{const h=state.history[q.id];return Boolean(h&&Number.isFinite(h.nextReviewAt)&&h.nextReviewAt<=Date.now())};
function reviewPriority(a,b){
  const ah=state.history[a.id]||{},bh=state.history[b.id]||{};
  const overdue=(h)=>Date.now()-(h.nextReviewAt||Date.now());
  return overdue(bh)-overdue(ah)||(bh.recentIncorrectCount||0)-(ah.recentIncorrectCount||0)||(ah.masteryStage||0)-(bh.masteryStage||0)||(bh.lastAnsweredAt||0)-(ah.lastAnsweredAt||0);
}
function dueReviews(filter='all'){
  const all=QUESTIONS.filter(isDue).sort(reviewPriority);
  if(all.length<REVIEW_FILTER_THRESHOLD||filter==='all')return all;
  const target=filter==='current'?level():Math.max(1,level()-1);
  return all.filter(q=>questionLevel(q)===target);
}
function seenIds(topicId){return new Set(state.seenQuestionIdsByTopic[topicId]||[])}
function unseenForTopic(topicId){const seen=seenIds(topicId);return QUESTIONS.filter(q=>q.topicId===topicId&&!seen.has(q.id))}
function rememberQuestions(questions){questions.forEach(q=>{const ids=state.seenQuestionIdsByTopic[q.topicId]||[];if(!ids.includes(q.id))ids.push(q.id);state.seenQuestionIdsByTopic[q.topicId]=ids;});}
function addUnique(target,candidates,count){for(const q of candidates){if(target.length>=count)break;if(!target.some(x=>x.id===q.id))target.push(q)}return target}
function balancedAnswerPositions(count,choiceCount=4){const positions=[];while(positions.length<count)positions.push(...shuffle(Array.from({length:choiceCount},(_,i)=>i)));return positions.slice(0,count)}
function makeOptionOrder(q,correctPosition){const others=shuffle(q.options.map((_,i)=>i).filter(i=>i!==q.correctAnswer)),order=Array(q.options.length),rest=[];for(let i=0;i<q.options.length;i++){if(i===correctPosition)order[i]=q.correctAnswer;else rest.push(i)}rest.forEach((slot,i)=>order[slot]=others[i]);return order}
function startSession(isReview=false,repeatTopicId=null){
  const current=repeatTopicId?TOPICS.find(t=>t.id===repeatTopicId):topic();
  let pool=[];
  if(isReview){
    pool=dueReviews(state.reviewFilter).slice(0,REVIEW_QUESTION_COUNT);
  }else if(repeatTopicId){
    pool=shuffle(unseenForTopic(repeatTopicId)).slice(0,MISSION_QUESTION_COUNT);
  }else{
    const scope=reviewLevels(),used=new Set([...Object.keys(state.history),...Object.values(state.seenQuestionIdsByTopic).flat()]),currentLevel=level();
    const overdue=QUESTIONS.filter(q=>scope.includes(questionLevel(q))&&isDue(q)).sort(reviewPriority);
    addUnique(pool,overdue,2);
    const unsettled=QUESTIONS.filter(q=>scope.includes(questionLevel(q))&&used.has(q.id)&&!isDue(q)&&(state.history[q.id].masteryStage||0)<3).sort((a,b)=>(state.history[a.id].masteryStage||0)-(state.history[b.id].masteryStage||0));
    addUnique(pool,shuffle(unsettled),5);
    const newCurrent=QUESTIONS.filter(q=>questionLevel(q)===currentLevel&&!used.has(q.id));
    addUnique(pool,shuffle(newCurrent.filter(q=>q.topicId===current.id)),10);
    addUnique(pool,shuffle(newCurrent),10);
    addUnique(pool,shuffle(QUESTIONS.filter(q=>scope.includes(questionLevel(q))&&!used.has(q.id))),10);
    addUnique(pool,shuffle(QUESTIONS.filter(q=>!used.has(q.id))),10);
    addUnique(pool,overdue,10);
    addUnique(pool,shuffle(unsettled),10);
    pool=pool.slice(0,MISSION_QUESTION_COUNT);
  }
  if(!pool.length)return;
  rememberQuestions(pool);
  const positions=balancedAnswerPositions(pool.length);
  state.session={questions:pool.map(q=>q.id),optionOrders:pool.map((q,i)=>makeOptionOrder(q,positions[i])),index:0,correct:0,mode:isReview?'review':repeatTopicId?'repeat':'learn',topicId:current.id,answers:[]};
  save();screen=isReview?'quiz':'lesson';render();if(state.bgm)setBgm(true);
}
function render(){const app=document.querySelector('#app');if(!activeProfile()){stopAudioPlayback();app.innerHTML=profiles();bind();return}if(!state.companionChosen&&screen==='home')screen='character';if(!isMissionScreen())stopAudioPlayback();app.innerHTML=screen==='home'?home():screen==='learn'?learn():screen==='lesson'?lesson():screen==='quiz'?quiz():screen==='feedback'?feedback():screen==='complete'?complete():screen==='character'?characters():screen==='achievements'?achievements():screen==='settings'?settings():screen==='mockSetup'?mockSetup():screen==='mockQuiz'?mockQuiz():screen==='mockFeedback'?mockFeedback():screen==='mockResult'?mockResult():screen==='pastList'?pastExamList():screen==='pastExam'?pastExam():pastExamResult(); bind();if(screen==='pastExam')requestAnimationFrame(()=>{const w=document.querySelector('.pdf-window');if(w)w.scrollTop=state.pastSession?.pdfScrollTop||0});if(screen==='mockQuiz')startMockTimer();else clearInterval(mockTimer);}
function profiles(){return `<div class="profile-page"><div class="profile-logo"><i></i>IT QUEST</div><h1>だれが学ぶ？</h1><p>ニックネームを選んで、前回の続きから始めよう。</p><div class="profile-list">${household.profiles.map(p=>`<button class="profile-card" data-profile="${p.id}"><span>${esc(p.name[0])}</span><b>${esc(p.name)}</b><small>PINで入る</small></button>`).join('')}</div><button class="new-profile" data-action="show-create">＋ 新しいプロフィール</button><section class="profile-form ${household.profiles.length?'hidden':''}"><h2>最初のプロフィールを作る</h2><label>ニックネーム<input id="nickname" maxlength="12" placeholder="例：ゆうと" autocomplete="nickname"></label><label>PIN（4〜6桁）<input id="new-pin" inputmode="numeric" maxlength="6" type="password" placeholder="数字だけ"></label><button class="primary" data-action="create-profile">作成して始める <b>›</b></button></section><section class="pin-form hidden"><h2 id="pin-name"></h2><p>PINを入力してね</p><input id="enter-pin" inputmode="numeric" maxlength="6" type="password" placeholder="PIN"><p class="form-error" id="pin-error"></p><button class="primary" data-action="enter-profile">このプロフィールで始める <b>›</b></button><button class="text-btn" data-action="cancel-pin">戻る</button></section><p class="profile-note">この端末・このブラウザにだけ保存されます。</p></div>`}
function shell(content,tab='home'){const c=character();return `<div class="app-shell"><header class="topbar"><div class="brand"><i></i>IT QUEST</div><div class="top-actions"><button class="top-badge navigator ${c.color}" data-nav="character" aria-label="相棒を選ぶ">${characterArt(state.selected,'badge')}<small>${c.name}</small></button><button class="top-badge learner" data-action="profiles" aria-label="学習者を切り替える">${esc(activeProfile().name[0])}</button><button class="top-badge settings-button ${tab==='settings'?'active':''}" data-nav="settings" aria-label="設定を開く">⚙</button></div></header>${content}<nav>${[['home','⌂','ホーム'],['learn','◈','学ぶ'],['character','◉','キャラ'],['achievements','★','実績']].map(x=>`<button class="nav ${tab===x[0]?'active':''}" data-nav="${x[0]}"><b>${x[1]}</b>${x[2]}</button>`).join('')}</nav></div>`}
function home(){const t=topic(),reviews=dueReviews('all').length,filtered=dueReviews(state.reviewFilter).length,pct=levelProgress(),mockReady=state.completed.length/TOPICS.length>=.7,filters=reviews>=REVIEW_FILTER_THRESHOLD?`<div class="review-filters" aria-label="復習範囲">${[['current','現在レベル中心'],['previous','前レベル中心'],['all','全レベル']].map(([value,label])=>`<button class="${state.reviewFilter===value?'active':''}" data-review-filter="${value}">${label}</button>`).join('')}</div>`:'';return shell(`${companionSpot('idle')}<section class="hero"><div class="eyebrow">今日のミッション</div><h1>${t.title}</h1><p>${t.summary}</p>${characterArt(state.selected,'hero-art')}</section><section class="stats"><div><small>レベル</small><b>Lv. ${level()}</b></div><div><small>XP</small><b>${state.xp}</b></div><div><small>連続学習</small><b>🔥 ${state.streak}日</b></div></section><section class="mission"><div class="section-head"><span>今日のチャレンジ</span><em>10問</em></div><div class="progress"><i style="width:${pct}%"></i></div><small>2問復習・3問未定着・5問新規を基本に自動構成</small><button class="primary" data-action="learn">ミッションを始める <b>›</b></button></section><section class="past-entry"><span>IPA公式問題</span><h2>年度別 過去問チャレンジ</h2><p>2020〜2026年の問題を年度ごとに選択。100問を採点し、苦手分野と強化ポイントを確認できます。</p><button class="outline" data-action="past-list">過去問を選ぶ</button></section><section class="mock-entry ${mockReady?'ready':''}"><span>${mockReady?'相棒からの提案':'本番形式'}</span><h2>${mockReady?'そろそろ実力を試してみよう':'模擬試験に挑戦'}</h2><p>${mockReady?'ここまでよく頑張った。今の実力を確かめてみる？':'100問・120分。準備できたらいつでも挑戦できます。'}</p><button class="outline" data-action="mock-setup">模擬試験を開く</button></section><section class="review-card"><div><span class="icon">↻</span><b>復習チャレンジ</b><p>${reviews?`優先度順の候補 ${reviews} 問から最大20問`:'今は復習期限を迎えた問題はありません'}</p></div><button class="outline" data-action="review" ${filtered?'':'disabled'}>復習する</button>${filters}</section>`,`home`)}
function learn(){return shell(`<section class="page-title"><span>学習</span><h1>学習マップ</h1><p>気になるテーマからいつでも挑戦できるよ。</p></section>${companionSpot('weakUnit')}<div class="topic-list">${TOPICS.map((t,i)=>`<button class="topic ${t.id===topic().id?'current':''}" data-topic="${t.id}"><b>${String(i+1).padStart(2,'0')}</b><span><small>${t.category}</small>${t.title}</span>${state.completed.includes(t.id)?'<em>✓</em>':'<i>›</i>'}</button>`).join('')}</div>`,'learn')}
function lesson(){const t=TOPICS.find(x=>x.id===state.session?.topicId)||topic(),g=EXAM_GUIDES[t.id]||{},stage=curriculumStage(),position=TOPICS.findIndex(x=>x.id===t.id)+1;return `<div class="lesson-page"><header><button class="back" data-action="quit">×</button><div class="brand"><i></i>IT QUEST</div><span></span></header><main><span class="lesson-label">Lv. ${level()}　${stage.name}　${position}/${TOPICS.length}</span><h1>${studyText(t.title)}</h1><p class="lesson-lead">${studyText(t.summary)}</p><section class="lesson-card focus-card"><h2>このレベルの学び方</h2><p>${studyText(levelLearningFocus())}</p></section><section class="lesson-card tip-card"><h2>過去問へつながる到達点</h2><p>${studyText(stage.goal)}</p></section><section class="lesson-card"><h2>まず全体像</h2><p>${studyText(g.overview||t.example)}</p></section><section class="lesson-card"><h2>大事な言葉</h2><div class="term-chips">${t.terms.map(x=>`<details><summary>${studyText(x)} <i>＋</i></summary><p>${studyText(termInfo(x))}</p></details>`).join('')}</div></section>${guideSection('仕組みと判断のポイント',g.points)}${guideSection('似た用語を見分ける',g.contrasts,'exam-contrasts')}${g.trap?`<section class="lesson-card trap-card"><h2>ひっかけ注意</h2><p>${studyText(g.trap)}</p></section>`:''}${g.examTip?`<section class="lesson-card tip-card"><h2>問題文の読み方</h2><p>${studyText(g.examTip)}</p></section>`:''}</main><div class="lesson-footer"><div class="coach visual">${characterArt(state.selected,'coach-art','thinking')}<p>「${pickLine('idle')}」</p></div><button class="primary" data-action="begin-quiz">${state.session.questions.length}問に挑戦 <b>›</b></button></div></div>`}
function quiz(){const s=state.session,q=QUESTIONS.find(x=>x.id===s.questions[s.index]),t=TOPICS.find(x=>x.id===q.topicId),order=s.optionOrders?.[s.index]||q.options.map((_,i)=>i);answerStarted=performance.now(); return `<div class="quiz-page"><header><button class="back" data-action="quit">×</button><div class="quiz-progress"><span>${s.mode==='review'?'復習チャレンジ':`${curriculumStage().name}：今日のミッション`}</span><div><i style="width:${s.index/s.questions.length*100}%"></i></div></div><b>${s.index+1}<small>/${s.questions.length}</small></b></header><main><div class="question-tag">${t.category}</div><h1>${esc(q.question)}</h1><p class="hint">答えを1つ選ぼう</p><div class="answers">${order.map((optionIndex,i)=>`<button data-answer="${i}"><span>${'ABCD'[i]}</span>${esc(q.options[optionIndex])}</button>`).join('')}</div></main><div class="coach visual">${characterArt(state.selected,'coach-art','thinking')}<p>「${pickLine('idle')}」</p></div></div>`}
function feedback(){const a=state.session.answers.at(-1),q=QUESTIONS.find(x=>x.id===a.id),good=a.correct,other=q.options.filter((_,i)=>i!==q.correctAnswer);return `<div class="feedback ${good?'good':'bad'}"><div class="result-mark">${good?'✓':'!'}</div>${companionFace(good?(a.voiceSituation||'correct'):'wrong')}<div class="feedback-copy">${good?'<span>ナイス！</span><h1>正解！ナイス判断！</h1>':`<h1 class="correct-answer">正解：${studyText(q.options[q.correctAnswer])}</h1><h2>ここがポイント</h2>`}<p>${studyText(q.detailedExplanation)}</p></div><section class="term-help"><b>ほかの選択肢も確認する</b><p>気になる言葉だけ、タップして見てみよう。</p>${other.map(word=>`<details><summary>「${studyText(word)}」って？ <i>＋</i></summary><div>${studyText(termInfo(word))}</div></details>`).join('')}</section><button class="primary" data-action="next">${state.session.index>=state.session.questions.length-1?'結果を見る':'次の問題へ'} <b>›</b></button></div>`}
function mockSetup(){return `<div class="mock-page"><header><button class="back" data-nav="home">×</button><div class="brand"><i></i>模擬試験</div><span></span></header><main class="mock-setup"><span class="lesson-label">本番と同じ問題数</span><h1>100問・120分に挑戦</h1><p>四肢択一で、ストラテジ35問・マネジメント20問・テクノロジ45問。採点は学習用の正答率です。</p><div class="mock-spec"><div><b>100</b><small>問題</small></div><div><b>120</b><small>分</small></div><div><b>4択</b><small>形式</small></div></div><h2>解説の表示を選ぶ</h2><button class="mode-card" data-mock-mode="friendly"><b>やさしい解説あり</b><span>1問ごとに、かみくだいた説明と豆知識を読む</span></button><button class="mode-card" data-mock-mode="none"><b>解説なし</b><span>回答後すぐ次へ進み、本番の集中と時間配分を練習する</span></button><p class="mock-note">問題はIPAシラバスを基に作成したオリジナルです。公式試験の採点方式を再現するものではありません。</p></main></div>`}
const shuffle=xs=>{const a=[...xs];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
function startMockExam(mode){const questions=shuffle(MOCK_QUESTIONS),positions=balancedAnswerPositions(questions.length);state.mockSession={ids:questions.map(q=>q.id),optionOrders:questions.map((q,i)=>makeOptionOrder(q,positions[i])),answers:Array(questions.length).fill(null),index:0,mode,startedAt:Date.now(),duration:120*60*1000,finishedAt:null};save();screen='mockQuiz';render()}
function mockCurrent(){const s=state.mockSession;return MOCK_QUESTIONS.find(q=>q.id===s.ids[s.index])}
function mockRemaining(){const s=state.mockSession;return Math.max(0,s.duration-(Date.now()-s.startedAt))}
function formatTime(ms){const sec=Math.ceil(ms/1000),m=Math.floor(sec/60),s=sec%60;return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function startMockTimer(){clearInterval(mockTimer);const tick=()=>{const el=document.querySelector('#mock-time');if(el)el.textContent=formatTime(mockRemaining());if(mockRemaining()<=0)finishMockExam()};tick();mockTimer=setInterval(tick,1000)}
function mockQuiz(){const s=state.mockSession,q=mockCurrent(),t=TOPICS.find(x=>x.id===q.topicId),answered=s.answers.filter(x=>x!==null).length,order=s.optionOrders?.[s.index]||q.options.map((_,i)=>i);return `<div class="quiz-page mock-quiz"><header><button class="back" data-action="mock-quit">×</button><div class="quiz-progress"><span>${t.category}　${s.index+1}/100</span><div><i style="width:${s.index}%"></i></div></div><b id="mock-time">${formatTime(mockRemaining())}</b></header><main><div class="question-tag">${t.title}</div><h1>${esc(q.question)}</h1><p class="hint">答えを1つ選ぼう　回答済み ${answered}問</p><div class="answers">${order.map((optionIndex,i)=>`<button data-mock-answer="${i}"><span>${'ABCD'[i]}</span>${esc(q.options[optionIndex])}</button>`).join('')}</div></main></div>`}
function answerMock(choice){const s=state.mockSession,q=mockCurrent(),order=s.optionOrders?.[s.index]||q.options.map((_,i)=>i);s.answers[s.index]=order[choice];save();if(s.mode==='friendly'){screen='mockFeedback';render()}else advanceMock()}
function mockFeedback(){const s=state.mockSession,q=mockCurrent(),choice=s.answers[s.index],good=choice===q.correctAnswer;return `<div class="feedback ${good?'good':'bad'}"><div class="result-mark">${good?'✓':'!'}</div><div class="feedback-copy"><span>${good?'正解！':'正解'}</span><h1 class="${good?'':'correct-answer'}">${studyText(q.options[q.correctAnswer])}</h1><p>${studyText(q.friendlyExplanation)}</p></div><section class="term-help"><b>もう一段くわしく</b><p>${studyText(q.detailedExplanation)}</p><details open><summary>豆知識・試験のコツ <i>＋</i></summary><div>${studyText(q.supplement)}</div></details></section><button class="primary" data-action="mock-next">${s.index===99?'結果を見る':'次の問題へ'} <b>›</b></button></div>`}
function advanceMock(){const s=state.mockSession;if(s.index>=99)finishMockExam();else{s.index++;save();screen='mockQuiz';render()}}
function finishMockExam(){clearInterval(mockTimer);const s=state.mockSession;if(!s||s.finishedAt)return;s.finishedAt=Date.now();save();screen='mockResult';render()}
function mockResult(){const s=state.mockSession,rows=Object.keys(MOCK_DOMAIN_TARGETS).map(domain=>{const qs=s.ids.map(id=>MOCK_QUESTIONS.find(q=>q.id===id)).map((q,i)=>({q,a:s.answers[i]})).filter(x=>TOPICS.find(t=>t.id===x.q.topicId).category===domain),ok=qs.filter(x=>x.a===x.q.correctAnswer).length;return {domain,ok,total:qs.length,pct:Math.round(ok/qs.length*100)}}),total=rows.reduce((n,x)=>n+x.ok,0),answered=s.answers.filter(x=>x!==null).length,pass=total>=60&&rows.every(x=>x.pct>=30);return `<div class="mock-page"><header><button class="back" data-nav="home">×</button><div class="brand"><i></i>模擬試験結果</div><span></span></header><main class="mock-result"><span class="lesson-label">${pass?'合格圏の目安':'復習ポイントあり'}</span><h1>${total}<small>/100問 正解</small></h1><p>回答 ${answered}問。これは正答率による学習用判定で、IRTを用いる公式得点とは異なります。</p><div class="domain-results">${rows.map(x=>`<div><span>${x.domain}</span><b>${x.ok}/${x.total}</b><div><i style="width:${x.pct}%"></i></div><small>${x.pct}%</small></div>`).join('')}</div><button class="primary" data-action="mock-retry">もう一度挑戦 <b>›</b></button><button class="text-btn" data-nav="home">ホームへ戻る</button></main></div>`}
function pastExamList(){return `<div class="past-page"><header><button class="back" data-nav="home">×</button><div class="brand"><i></i>年度別 過去問</div><span></span></header><main class="past-list"><span class="lesson-label">IPA公式公開問題</span><h1>挑戦する年度を選ぶ</h1><p>各年度100問です。問題冊子を見ながらアプリに答えを入力し、最後に採点します。</p><div class="year-list">${PAST_EXAMS.map(exam=>{const h=state.pastHistory?.[exam.year];return `<button class="year-card" data-past-year="${exam.year}"><span><small>${exam.reiwa}</small><b>${exam.year}年</b></span><span>${h?`最高 ${h.best}/100`:'未挑戦'}<i>›</i></span></button>`}).join('')}</div><section class="source-note"><b>出典と解説について</b><p>問題・解答例はIPA公開資料です。IPAは解説を公開していないため、解き方と中学生向け説明は本アプリ独自の学習補助です。</p><a href="https://www3.jitec.ipa.go.jp/JitesCbt/html/openinfo/questions.html" target="_blank" rel="noopener">IPAの過去問題ページ ↗</a></section></main></div>`}
function startPastExam(year){const exam=PAST_EXAMS.find(x=>x.year===year);state.pastSession={year:exam.year,answers:Array(100).fill(null),index:0,pdfPage:1,pdfScrollTop:0,startedAt:Date.now(),finishedAt:null};save();screen='pastExam';render()}
function currentPastExam(){return PAST_EXAMS.find(x=>x.year===state.pastSession?.year)||PAST_EXAMS[0]}
function pastPageImage(exam,page,format='jpg'){return `assets/past-exams/pages/${exam.file}/page-${String(page).padStart(2,'0')}.${format}`}
function pastExam(){const s=state.pastSession,exam=currentPastExam(),n=s.index+1,domain=pastDomain(n),answered=s.answers.filter(Boolean).length,page=Math.max(1,Math.min(exam.pages,s.pdfPage||1));s.pdfPage=page;return `<div class="past-page past-taking"><header><button class="back" data-action="past-quit">×</button><div class="quiz-progress"><span>${exam.year}年　公式過去問</span><div><i id="past-progress" style="width:${answered}%"></i></div></div><b id="past-answered-top">${answered}<small>/100回答</small></b></header><main class="past-split"><section class="pdf-pane" aria-label="問題冊子"><div class="pdf-toolbar"><button data-pdf-move="-1" ${page===1?'disabled':''}>‹ 前のページ</button><span><b id="pdf-page-number">${page}</b> / ${exam.pages}</span><button data-pdf-move="1" ${page===exam.pages?'disabled':''}>次のページ ›</button></div><div class="pdf-window" tabindex="0"><div id="pdf-load-error" class="pdf-load-error hidden"><b>問題ページを表示できませんでした</b><p>ページ画像をもう一度読み込みます。</p><button data-action="pdf-retry">再読み込み</button></div><picture id="past-pdf-picture"><img id="past-pdf-page" src="${pastPageImage(exam,page)}" alt="${exam.year}年度 問題冊子 ${page}ページ"></picture></div></section><section class="answer-pane"><div class="answer-pane-head"><div><span class="lesson-label">${domain}</span><h1>問 ${n}</h1></div><small>上の冊子から問${n}を確認</small></div><div class="past-answer"><p class="hint">回答を1つ選ぶ</p><div class="answer-letters">${['A','B','C','D'].map((letter,i)=>`<button class="${s.answers[s.index]===letter?'selected':''}" data-past-answer="${letter}"><span>${'アイウエ'[i]}</span><small>${letter}</small></button>`).join('')}</div></div><div class="past-nav"><button class="outline" data-past-move="-1" ${s.index===0?'disabled':''}>‹ 前の問題</button><button class="outline" data-past-move="1" ${s.index===99?'disabled':''}>次の問題 ›</button></div><details class="number-jump"><summary>問題番号から移動（回答済み <span id="past-answered-inline">${answered}</span>問）</summary><div>${Array.from({length:100},(_,i)=>`<button class="${s.answers[i]?'answered':''} ${i===s.index?'current':''}" data-past-index="${i}">${i+1}</button>`).join('')}</div></details><button class="primary" data-action="past-finish">採点する <b>›</b></button><p class="past-save-note">問題ページと回答位置は別々に保存されます。</p></section></main></div>`}
function showPastPdfError(show){document.querySelector('#pdf-load-error')?.classList.toggle('hidden',!show);document.querySelector('#past-pdf-picture')?.classList.toggle('hidden',show)}
function bindPastPdfViewer(){
  const image=document.querySelector('#past-pdf-page'),windowEl=document.querySelector('.pdf-window'),picture=document.querySelector('#past-pdf-picture'),retry=document.querySelector('[data-action="pdf-retry"]');
  if(!image)return;
  let zoom=1,pinchStart=null;
  const setZoom=value=>{
    zoom=Math.max(1,Math.min(3,value));
    if(picture)picture.style.width=`${zoom*100}%`;
  };
  const touchDistance=touches=>Math.hypot(touches[0].clientX-touches[1].clientX,touches[0].clientY-touches[1].clientY);
  image.addEventListener('load',()=>showPastPdfError(false));
  image.addEventListener('error',()=>showPastPdfError(true));
  image.addEventListener('touchstart',event=>{
    if(event.touches.length===2)pinchStart={distance:touchDistance(event.touches),zoom};
  },{passive:true});
  image.addEventListener('touchmove',event=>{
    if(event.touches.length!==2||!pinchStart)return;
    event.preventDefault();
    setZoom(pinchStart.zoom*touchDistance(event.touches)/pinchStart.distance);
  },{passive:false});
  image.addEventListener('touchend',event=>{if(event.touches.length<2)pinchStart=null},{passive:true});
  document.querySelectorAll('[data-pdf-move]').forEach(button=>button.onclick=()=>{
    const s=state.pastSession,exam=currentPastExam();
    s.pdfPage=Math.max(1,Math.min(exam.pages,(s.pdfPage||1)+(+button.dataset.pdfMove)));
    s.pdfScrollTop=0;save();showPastPdfError(false);
    image.src=pastPageImage(exam,s.pdfPage);
    image.alt=`${exam.year}年度 問題冊子 ${s.pdfPage}ページ`;
    const label=document.querySelector('#pdf-page-number');
    if(label)label.textContent=s.pdfPage;if(windowEl)windowEl.scrollTop=0;
    document.querySelectorAll('[data-pdf-move]').forEach(x=>x.disabled=(+x.dataset.pdfMove<0?s.pdfPage===1:s.pdfPage===exam.pages));
  });
  retry?.addEventListener('click',()=>{
    const s=state.pastSession,exam=currentPastExam(),stamp=Date.now();showPastPdfError(false);
    image.src=`${pastPageImage(exam,s.pdfPage||1)}?v=${stamp}`;
  });
}
function pastRows(s,exam){return Object.entries(PAST_DOMAIN_INFO).map(([domain,info])=>{const [start,end]=info.range,total=end-start+1,ok=Array.from({length:total},(_,i)=>start+i).filter(n=>s.answers[n-1]===exam.answers[n-1]).length;return {domain,info,ok,total,pct:Math.round(ok/total*100)}})}
function finishPastExam(){const s=state.pastSession,exam=currentPastExam(),total=s.answers.filter((answer,i)=>answer===exam.answers[i]).length;s.finishedAt=Date.now();state.pastHistory??={};const old=state.pastHistory[exam.year]||{};state.pastHistory[exam.year]={best:Math.max(old.best||0,total),last:total,completedAt:Date.now()};save();screen='pastResult';render()}
function pastExamResult(){const s=state.pastSession,exam=currentPastExam(),rows=pastRows(s,exam),total=rows.reduce((sum,row)=>sum+row.ok,0),answered=s.answers.filter(Boolean).length,pass=total>=60&&rows.every(row=>row.pct>=30),weak=[...rows].sort((a,b)=>a.pct-b.pct)[0],missed=Array.from({length:100},(_,i)=>i+1).filter(n=>s.answers[n-1]!==exam.answers[n-1]);return `<div class="past-page"><header><button class="back" data-action="past-close-result">×</button><div class="brand"><i></i>${exam.year}年 結果</div><span></span></header><main class="past-result"><span class="lesson-label">${pass?'合格圏の目安':'ここから伸ばせる'}</span><h1>${total}<small>/100問 正解</small></h1><p>回答 ${answered}問。公式試験はIRT方式なので、これは正答数による学習用の目安です。</p><div class="domain-results">${rows.map(row=>`<div><span>${row.domain}</span><b>${row.ok}/${row.total}</b><div><i style="width:${row.pct}%"></i></div><small>${row.pct}%</small></div>`).join('')}</div><section class="strength-advice"><span>合格へ向けた強化ポイント</span><h2>${weak.domain}を優先しよう</h2><p>${weak.info.advice}</p><ul><li>間違えた問題を「なぜその答えになるか」まで言葉にする</li><li>1週間以内に同じ年度をもう一度解き、80問正解を目標にする</li><li>全分野30%以上を保ちつつ、総合60%以上を安定して取る</li></ul></section><section class="answer-review"><div class="review-head"><div><span class="lesson-label">回答例・解説</span><h2>${missed.length?`要復習 ${missed.length}問`:'全問正解！'}</h2></div><a href="${exam.answerPdf}" target="_blank">公式解答例 ↗</a></div>${missed.length?missed.map(n=>{const domain=pastDomain(n),info=PAST_DOMAIN_INFO[domain],mine=s.answers[n-1]||'未回答',correct=exam.answers[n-1],jp='アイウエ'[['A','B','C','D'].indexOf(correct)];return `<details><summary>問${n}　あなた：${mine} ／ 正解：${jp}（${correct}） <i>＋</i></summary><div><b>解き方の解説</b><p>${studyText(info.explanation)}</p><b>中学生向けにいうと</b><p class="junior-explanation">${studyText(info.junior)}</p><a href="${exam.questionPdf}" target="_blank">公式問題冊子で問${n}を確認 ↗</a></div></details>`}).join(''):'<p class="perfect-note">すべて正解です。別年度にも挑戦して、知識を安定させましょう。</p>'}</section><button class="primary" data-action="past-retry">この年度にもう一度挑戦 <b>›</b></button><button class="text-btn" data-action="past-years">年度選択へ</button></main></div>`}
function complete(){const s=state.session,gained=s.correct*10+20,c=character(),unlocked=s.unlocked||[],reward=s.rewardItems?.[0],nextTopic=topic(),remaining=s.mode==='review'?0:unseenForTopic(s.topicId).length,canRepeat=remaining>=MISSION_QUESTION_COUNT,nextStep=s.mode==='review'?`<section class="lesson-card"><h2>復習できました</h2><p>期限と想起成功段階は更新済みです。</p></section>`:`<section class="lesson-card tip-card"><h2>次の予習</h2><p>Lv. ${level()}の重点は「${studyText(levelLearningFocus())}」。次は「${studyText(nextTopic.title)}」です。</p></section>`;const actions=s.mode==='review'?`<button class="primary" data-nav="home">ホームへ戻る <b>›</b></button>`:`<div class="complete-actions"><button class="primary" data-action="next-topic">次のテーマへ <b>›</b></button><button class="outline repeat-theme" data-action="same-theme" ${canRepeat?'':'disabled'}>同じテーマをもう1回</button>${canRepeat?`<small>未出題の問題が ${remaining} 問あります</small>`:'<small>このテーマの新規問題は完了。復習チャレンジで確認できます</small>'}</div>`;return shell(`<section class="complete ${s.correct===s.questions.length?'perfect-clear':''}"><div class="celebrate">✦</div><span>ミッション完了</span><h1>${s.correct===s.questions.length?'全問正解！パーフェクト！':'今日のミッション完了！'}</h1><div class="result-score"><b>${s.correct}</b><small>/ ${s.questions.length}問 正解</small></div><div class="reward"><div>+${gained} <small>XP</small></div><div>🔥 ${state.streak} <small>日連続</small></div></div>${nextStep}<div class="character-quote">${characterArt(state.selected,'quote-art','cheer')}<p>「${pickLine('complete')}」<small>— ${c.name}</small></p></div>${s.levelUps?.length?`<section class="level-up-panel ${s.chestOpened?'opened':''}"><span>LEVEL UP!</span><h2>Lv. ${s.levelUps.at(-1)} になった！</h2>${s.chestOpened?`<div class="new-item"><b>NEW ITEM!</b><div class="item-icon">✦</div><strong>${reward?.name||'特別アイテム'}</strong><small>${c.name}専用アイテムを獲得</small></div>`:`<button class="treasure" data-action="open-chest" aria-label="玉手箱を開ける"><span>✦</span><b>玉手箱を開ける</b></button>`}</section>`:''}${unlocked.length?`<div class="unlock">★ 実績を解除：${unlocked.join('、')}</div>`:''}${actions}</section>`,'home')}
function characters(){return shell(`<section class="page-title companion-title"><span>SELECT PARTNER</span><h1>今日は誰と勉強する？</h1><p>見た目は強そう。でも、3人ともあなたの味方です。</p></section><div class="navigator-compare">${Object.keys(CHARACTERS).map(id=>{let x=character(id);return `<button class="character-card ${id} ${state.selected===id&&state.companionChosen?'selected':''}" data-character="${id}">${characterArt(id,'card-art')}<div class="character-summary"><small>${x.role}</small><b>${x.name}</b><p class="character-line">「${x.tag}」</p><dl><div><dt>声かけ</dt><dd>${x.style}</dd></div><div><dt>こんな人に</dt><dd>${x.fit}</dd></div></dl></div><em>${state.selected===id&&state.companionChosen?'✓ 今日の相棒':'この相棒と勉強する'}</em></button>`}).join('')}</div><p class="navigator-note">相棒はいつでも変更できます。問題・難易度・XP・進捗は変わりません。</p><section class="cosmetics"><b>獲得したコレクション</b><div><span>⚡ スターター</span>${state.unlocked.map(x=>`<span>✦ ${esc(x.name||x)}</span>`).join('')}</div></section>`,'character')}
function achievements(){const all=[['はじめの一歩','最初のミッションを完了'],['100問突破','100問に回答'],['100問正解','100問正解'],['セキュリティ入門','セキュリティ問題に正解'],['ネットワーク探検家','ネットワーク問題に正解'],['AIチャレンジャー','AI問題に正解'],['7日連続','7日連続で学習']];return shell(`<section class="page-title"><span>実績</span><h1>実績</h1><p>${state.achievements.length} / ${all.length} 解除済み</p></section>${companionSpot('idle')}<div class="achievement-list">${all.map(a=>`<div class="achievement ${state.achievements.includes(a[0])?'earned':''}"><span>${state.achievements.includes(a[0])?'★':'◇'}</span><div><b>${a[0]}</b><small>${a[1]}</small></div></div>`).join('')}</div>`,'achievements')}
function settings(){const p=activeProfile();return shell(`<section class="page-title settings-title"><span>設定</span><h1>プロフィールと音</h1><p>このプロフィールの設定を変更できます。</p></section><section class="settings-card"><div class="settings-card-head"><span>☺</span><div><b>プロフィール</b><small>ニックネームとPIN</small></div></div><label>ニックネーム<input id="settings-nickname" maxlength="12" value="${esc(p.name)}" autocomplete="nickname"></label><button class="outline settings-save" data-action="save-nickname">ニックネームを保存</button><div class="settings-divider"></div><b class="settings-subtitle">PINを再設定</b><label>現在のPIN<input id="current-pin" inputmode="numeric" maxlength="6" type="password" placeholder="4〜6桁"></label><label>新しいPIN<input id="reset-pin" inputmode="numeric" maxlength="6" type="password" placeholder="4〜6桁"></label><p class="form-error" id="settings-error"></p><button class="outline settings-save" data-action="reset-pin">PINを変更</button></section><section class="settings-card"><div class="settings-card-head"><span>♫</span><div><b>音設定</b><small>学習中のBGMと効果音</small></div><button class="sound-toggle ${state.bgm?'on':''}" data-action="settings-bgm" role="switch" aria-checked="${state.bgm}"><i></i><span>${state.bgm?'ON':'OFF'}</span></button></div><div class="volume-row"><label for="volume">音量 <output id="volume-value">${state.volume}%</output></label><input id="volume" type="range" min="0" max="100" step="5" value="${state.volume}" ${state.bgm?'':'disabled'}><div class="volume-scale"><span>小</span><span class="default-mark">初期値 ${DEFAULT_VOLUME}</span><span>大</span></div></div><button class="text-btn volume-default" data-action="default-volume">初期音量に戻す</button><p class="sound-note">初期設定はON・音量${DEFAULT_VOLUME}。端末の音量もあわせて調整してください。</p></section>`,'settings')}
function newAchievements(){let a=[];if(state.answered>=10)a.push('はじめの一歩');if(state.answered>=100)a.push('100問突破');if(state.correct>=100)a.push('100問正解');if(state.streak>=7)a.push('7日連続'); let hist=Object.entries(state.history);if(hist.some(([id,h])=>h.correctCount&&QUESTIONS.find(q=>q.id===id).topicId==='security'))a.push('セキュリティ入門');if(hist.some(([id,h])=>h.correctCount&&QUESTIONS.find(q=>q.id===id).topicId==='network'))a.push('ネットワーク探検家');if(hist.some(([id,h])=>h.correctCount&&QUESTIONS.find(q=>q.id===id).topicId==='ai'))a.push('AIチャレンジャー');return a.filter(x=>!state.achievements.includes(x));}
function bind(){document.querySelectorAll('[data-nav]').forEach(e=>e.onclick=()=>{screen=e.dataset.nav;render()});document.querySelectorAll('[data-topic]').forEach(e=>e.onclick=()=>{state.completed=TOPICS.slice(0,TOPICS.findIndex(t=>t.id===e.dataset.topic)).map(t=>t.id);save();screen='home';render()});document.querySelectorAll('[data-character]').forEach(e=>e.onclick=()=>{const first=!state.companionChosen;state.selected=e.dataset.character;state.companionChosen=true;save();screen=first?'home':'character';render()});document.querySelectorAll('[data-profile]').forEach(e=>e.onclick=()=>{document.querySelector('.profile-list').classList.add('hidden');document.querySelector('.new-profile').classList.add('hidden');document.querySelector('.pin-form').classList.remove('hidden');document.querySelector('#pin-name').textContent=`${household.profiles.find(p=>p.id===e.dataset.profile).name} のPIN`;document.querySelector('.pin-form').dataset.profile=e.dataset.profile;document.querySelector('#enter-pin').focus();});document.querySelector('[data-action="show-create"]')?.addEventListener('click',()=>document.querySelector('.profile-form').classList.remove('hidden'));document.querySelector('[data-action="create-profile"]')?.addEventListener('click',()=>{const name=document.querySelector('#nickname').value.trim(),pin=document.querySelector('#new-pin').value;if(!name||!/^\d{4,6}$/.test(pin)){alert('ニックネームと4〜6桁の数字PINを入力してね。');return}const id=crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`;household.profiles.push({id,name,pinHash:pinHash(pin)});const legacy=localStorage.getItem(KEY);localStorage.setItem(profileKey(id),legacy||JSON.stringify(fresh()));localStorage.removeItem(KEY);loadProfile(id);screen='character';render();});document.querySelector('[data-action="enter-profile"]')?.addEventListener('click',()=>{const form=document.querySelector('.pin-form'),p=household.profiles.find(x=>x.id===form.dataset.profile);if(pinHash(document.querySelector('#enter-pin').value)!==p.pinHash){document.querySelector('#pin-error').textContent='PINが違うみたい。もう一度入力してね。';return}loadProfile(p.id);screen='home';render();});document.querySelector('[data-action="cancel-pin"]')?.addEventListener('click',render);document.querySelector('[data-action="profiles"]')?.addEventListener('click',()=>{leaveProfile();render()});document.querySelector('[data-action="bgm"]')?.addEventListener('click',()=>{setBgm(!state.bgm);render()});document.querySelector('[data-action="learn"]')?.addEventListener('click',()=>startSession());document.querySelector('[data-action="review"]')?.addEventListener('click',()=>startSession(true));document.querySelector('[data-action="again"]')?.addEventListener('click',()=>startSession());document.querySelector('[data-action="open-chest"]')?.addEventListener('click',()=>{state.session.chestOpened=true;save();sound('complete');render()});document.querySelector('[data-action="begin-quiz"]')?.addEventListener('click',()=>{screen='quiz';render()});document.querySelector('[data-action="quit"]')?.addEventListener('click',()=>{screen='home';render()});document.querySelector('[data-action="next"]')?.addEventListener('click',next);document.querySelectorAll('[data-answer]').forEach(e=>e.onclick=()=>answer(+e.dataset.answer));document.querySelector('[data-action="mock-setup"]')?.addEventListener('click',()=>{screen='mockSetup';render()});document.querySelectorAll('[data-mock-mode]').forEach(e=>e.onclick=()=>startMockExam(e.dataset.mockMode));document.querySelectorAll('[data-mock-answer]').forEach(e=>e.onclick=()=>answerMock(+e.dataset.mockAnswer));document.querySelector('[data-action="mock-next"]')?.addEventListener('click',advanceMock);document.querySelector('[data-action="mock-retry"]')?.addEventListener('click',()=>{screen='mockSetup';render()});document.querySelector('[data-action="mock-quit"]')?.addEventListener('click',()=>{screen='home';render()});document.querySelector('[data-action="past-list"]')?.addEventListener('click',()=>{screen='pastList';render()});document.querySelectorAll('[data-past-year]').forEach(e=>e.onclick=()=>startPastExam(+e.dataset.pastYear));document.querySelectorAll('[data-past-answer]').forEach(e=>e.onclick=()=>{const s=state.pastSession;s.answers[s.index]=e.dataset.pastAnswer;save();document.querySelectorAll('[data-past-answer]').forEach(button=>button.classList.toggle('selected',button===e));const answered=s.answers.filter(Boolean).length,top=document.querySelector('#past-answered-top');if(top?.firstChild)top.firstChild.nodeValue=answered;const inline=document.querySelector('#past-answered-inline'),progress=document.querySelector('#past-progress'),jump=document.querySelector(`[data-past-index="${s.index}"]`);if(inline)inline.textContent=answered;if(progress)progress.style.width=`${answered}%`;jump?.classList.add('answered')});document.querySelectorAll('[data-pdf-move]').forEach(e=>e.onclick=()=>{const s=state.pastSession,exam=currentPastExam();s.pdfPage=Math.max(1,Math.min(exam.pages,(s.pdfPage||1)+(+e.dataset.pdfMove)));s.pdfScrollTop=0;save();const image=document.querySelector('#past-pdf-page'),label=document.querySelector('#pdf-page-number'),windowEl=document.querySelector('.pdf-window'),buttons=[...document.querySelectorAll('[data-pdf-move]')];if(image){image.src=pastPageImage(exam,s.pdfPage);image.alt=`${exam.year}年度 問題冊子 ${s.pdfPage}ページ`}if(label)label.textContent=s.pdfPage;if(windowEl)windowEl.scrollTop=0;buttons.forEach(button=>button.disabled=(+button.dataset.pdfMove<0?s.pdfPage===1:s.pdfPage===exam.pages))});document.querySelector('.pdf-window')?.addEventListener('scroll',e=>{state.pastSession.pdfScrollTop=e.currentTarget.scrollTop},{passive:true});document.querySelectorAll('[data-past-move]').forEach(e=>e.onclick=()=>{state.pastSession.index=Math.max(0,Math.min(99,state.pastSession.index+(+e.dataset.pastMove)));save();render()});document.querySelectorAll('[data-past-index]').forEach(e=>e.onclick=()=>{state.pastSession.index=+e.dataset.pastIndex;save();render()});document.querySelector('[data-action="past-finish"]')?.addEventListener('click',()=>{const unanswered=state.pastSession.answers.filter(x=>!x).length;if(unanswered&&!confirm(`未回答が ${unanswered} 問あります。このまま採点しますか？`))return;finishPastExam()});document.querySelector('[data-action="past-quit"]')?.addEventListener('click',()=>{screen='pastList';render()});document.querySelector('[data-action="past-close-result"]')?.addEventListener('click',()=>{screen='pastList';render()});document.querySelector('[data-action="past-retry"]')?.addEventListener('click',()=>startPastExam(currentPastExam().year));document.querySelector('[data-action="past-years"]')?.addEventListener('click',()=>{screen='pastList';render()});bindSettings();armAudio();}
function bindSettings(){
  bindPastPdfViewer();
  document.querySelector('[data-action="next-topic"]')?.addEventListener('click',()=>startSession());
  document.querySelector('[data-action="same-theme"]')?.addEventListener('click',()=>startSession(false,state.session.topicId));
  document.querySelectorAll('[data-review-filter]').forEach(button=>button.addEventListener('click',()=>{state.reviewFilter=button.dataset.reviewFilter;save();render()}));
  document.querySelectorAll('[data-topic]').forEach(button=>button.onclick=()=>{const index=TOPICS.findIndex(t=>t.id===button.dataset.topic);if(index<0)return;state.missionIndex=index;state.completed=TOPICS.slice(0,index).map(t=>t.id);save();screen='home';render()});
  document.querySelector('[data-action="save-nickname"]')?.addEventListener('click',()=>{const input=document.querySelector('#settings-nickname'),name=input.value.trim();if(!name){input.focus();return}activeProfile().name=name;localStorage.setItem(HOUSEHOLD_KEY,JSON.stringify(household));render()});
  document.querySelector('[data-action="reset-pin"]')?.addEventListener('click',()=>{const current=document.querySelector('#current-pin').value,nextPin=document.querySelector('#reset-pin').value,error=document.querySelector('#settings-error'),p=activeProfile();if(pinHash(current)!==p.pinHash){error.textContent='現在のPINが違います。';return}if(!/^\d{4,6}$/.test(nextPin)){error.textContent='新しいPINは4〜6桁の数字にしてください。';return}p.pinHash=pinHash(nextPin);localStorage.setItem(HOUSEHOLD_KEY,JSON.stringify(household));error.classList.add('success');error.textContent='PINを変更しました。';document.querySelector('#current-pin').value='';document.querySelector('#reset-pin').value=''});
  document.querySelector('[data-action="settings-bgm"]')?.addEventListener('click',()=>{setBgm(!state.bgm);render()});
  document.querySelector('#volume')?.addEventListener('input',e=>{state.volume=Number(e.target.value);document.querySelector('#volume-value').value=`${state.volume}%`;save()});
  document.querySelector('[data-action="default-volume"]')?.addEventListener('click',()=>{state.volume=DEFAULT_VOLUME;save();render()});
}
let audioUnlockArmed=false;
function armAudio(){if(audioUnlockArmed||!activeProfile()||!state.bgm||!isMissionScreen()||bgmTimer)return;audioUnlockArmed=true;document.addEventListener('pointerdown',()=>{audioUnlockArmed=false;if(activeProfile()&&state.bgm&&isMissionScreen()&&!bgmTimer)setBgm(true)},{once:true})}
function answer(choice){const s=state.session,q=QUESTIONS.find(x=>x.id===s.questions[s.index]),order=s.optionOrders?.[s.index]||q.options.map((_,i)=>i),correct=order[choice]===q.correctAnswer,time=Math.round(performance.now()-answerStarted),h=state.history[q.id]||{correctCount:0,incorrectCount:0,repetitionCount:0,masteryStage:0,correctStreak:0,recentIncorrectCount:0},voiceSituation=correct?((h.recentIncorrectCount||0)>0?'comebackCorrect':h.correctCount>0?'memoryCorrect':'correct'):'wrong';h.lastAnsweredAt=Date.now();h.lastResponseTime=time;h.averageResponseTime=h.averageResponseTime?Math.round((h.averageResponseTime+h.lastResponseTime)/2):time;h.repetitionCount++;if(correct){h.correctCount++;h.correctStreak=(h.correctStreak||0)+1;h.masteryStage=Math.min(5,(h.masteryStage||0)+1);h.recentIncorrectCount=Math.max(0,(h.recentIncorrectCount||0)-1);const intervals=[0,3,7,14,30,60];h.nextReviewAt=Date.now()+intervals[h.masteryStage]*864e5;s.correct++;state.correct++;sound(s.correct>1?'combo':'correct');}else{h.incorrectCount++;h.correctStreak=0;h.masteryStage=0;h.recentIncorrectCount=Math.min(5,(h.recentIncorrectCount||0)+1);h.nextReviewAt=Date.now();sound('wrong');}state.history[q.id]=h;state.answered++;s.answers.push({id:q.id,correct,time,voiceSituation,masteryStage:h.masteryStage});save();screen='feedback';render();}
function next(){const s=state.session;if(s.index>=s.questions.length-1){sound('complete');const completedTopic=TOPICS.find(x=>x.id===s.topicId),before=level();if(s.mode==='learn'){if(completedTopic&&!state.completed.includes(completedTopic.id))state.completed.push(completedTopic.id);state.missionIndex=Math.min(TOPICS.length,state.missionIndex+1);}state.xp+=s.correct*10+20;const after=level();s.levelUps=after>before?Array.from({length:after-before},(_,i)=>before+i+1):[];s.rewardItems=s.levelUps.map(l=>({id:`${state.selected}-${l}`,characterId:state.selected,type:l%2?'equipment':'outfit',name:REWARD_NAMES[l],unlockLevel:l}));for(const item of s.rewardItems)if(!state.unlocked.some(x=>(x.id||x)===item.id))state.unlocked.push(item);s.chestOpened=false;const d=today();if(state.lastStudy!==d){const yesterday=new Date(Date.now()-864e5).toISOString().slice(0,10);state.streak=state.lastStudy===yesterday?state.streak+1:1;state.lastStudy=d;}const unlocked=newAchievements();s.unlocked=unlocked;state.achievements.push(...unlocked);save();screen='complete';render();}else{state.session.index++;save();screen='quiz';render();}}
render();
